void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;

    // Time varying pixel color
    vec3 col = 0.5 + 0.5*tan(iTime+  uv.xyx  +  uv.yxy + vec3(0,2,4));


    float col1mult = ((sin(iTime)+1.0)/2.0);
    // Output to screen
    fragColor = vec4(col+sin(fragCoord.x-20.0*((sin(iTime/5.0)+sin(iTime/15.0))*20.0)),1.0);
}
